using System.Collections.Immutable;
using Aict.Core;
using Aict.Beta;
using Aict.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;
namespace Aict.Core.Tests;
[TestClass] public class ExceptionCatalogTests {
    static RuleGroup Group()=>new(){Id=Guid.NewGuid(),Name="例外",WebsiteMode=TargetMode.BlockSelected,WebsiteDomains=["*bilibili*"],WebsiteExceptions=["www.bilibili.com/bangumi/play/ep65703","*favlist*"],AlwaysBlock=true};
    [TestMethod] public void LegacyJsonHasNoNewFieldAndOldPendingStillApplies(){var g=Group();var p=new PolicyConfiguration{Groups=[g],ChangeDelay=TimeSpan.FromMinutes(1)};Assert.IsFalse(PolicyJson.Serialize(p).Contains("websiteExceptionDetails"));var copy=PolicyJson.Parse<PolicyConfiguration>(PolicyJson.Serialize(p));Assert.AreEqual(2,ExceptionCatalog.Rows(copy.Groups[0]).Length);Assert.IsTrue(ExceptionCatalog.Rows(copy.Groups[0]).All(r=>r.Note==""&&r.Group==""));}
    [TestMethod] public void NotesRoundtripButHaveNoEffectOnMatchingOrWebFingerprint(){var g=Group();var annotated=ExceptionCatalog.SetRows(g,[new(g.WebsiteExceptions[0],"课程第3讲","学习"),new(g.WebsiteExceptions[1],"收藏夹","资料")]);var p=new PolicyConfiguration{Groups=[g]};var q=p with{Groups=[annotated]};PolicyValidation.Validate(q);Assert.IsTrue(ExceptionCatalog.SameEnforcement(p,q));Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(p,q,DateTimeOffset.UtcNow));Assert.AreEqual("课程第3讲",PolicyJson.Parse<PolicyConfiguration>(PolicyJson.Serialize(q)).Groups[0].WebsiteExceptionDetails!.Value[0].Note);var now=DateTimeOffset.UtcNow;var s=new EngineSnapshot{Policy=p,Clock=new(now,true)};Assert.AreEqual(Plans.Web(s,true).Fingerprint,Plans.Web(s with{Policy=q},true).Fingerprint);Assert.IsFalse(RuleEngine.Matches(annotated,new(null,"www.bilibili.com"){WebsiteUrl="https://www.bilibili.com/bangumi/play/ep65703"}));}
    [TestMethod] public void UpdatingAnnotationsPreservesPendingDeadlineAndFrozenScopeAcrossRestart(){var g=Group();var p=new PolicyConfiguration{Groups=[g],ChangeDelay=TimeSpan.FromMinutes(1)};var now=DateTimeOffset.UtcNow;var s=ChangeQueue.Submit(new(){Policy=p,Clock=new(now,true)},p with{Groups=[g with{WebsiteExceptions=g.WebsiteExceptions.Add("*history*")}]},new(now,true));s=s with{Pending=s.Pending! with{ApplyAtDeadline=true}};var old=s.Pending!;var next=ExceptionCatalog.UpdateAnnotations(s,g.Id,[new(g.WebsiteExceptions[0],"课程","学习"),new("*history*","历史","常用")]);Assert.AreEqual(old.Id,next.Pending!.Id);Assert.AreEqual(old.NotBeforeUtc,next.Pending.NotBeforeUtc);Assert.AreEqual(old.SubmittedUtc,next.Pending.SubmittedUtc);Assert.IsTrue(ExceptionCatalog.SameEnforcement(s.Policy,next.Policy));var oldTarget=PolicyJson.Parse<PolicyConfiguration>(old.TargetJson);var newTarget=PolicyJson.Parse<PolicyConfiguration>(next.Pending.TargetJson);Assert.IsTrue(ExceptionCatalog.SameEnforcement(oldTarget,newTarget));var path=Path.Combine(Environment.GetEnvironmentVariable("AICT_TEST_ROOT")??Path.GetTempPath(),"notes-"+Guid.NewGuid().ToString("N")+".sqlite");StateRepository.CreateNew(path,next);var saved=StateRepository.OpenExisting(path).Read().Snapshot;var applied=ChangeQueue.TryApply(saved,new(now.AddMinutes(1),true));Assert.AreEqual(ApplyStatus.Applied,applied.Status);Assert.AreEqual("历史",ExceptionCatalog.Rows(applied.Snapshot.Policy.Groups[0]).Single(r=>r.Pattern=="*history*").Note);}
    [TestMethod] public void AnnotationApiCannotAddTargetsOrAcceptUnboundedNotes(){var g=Group();var state=new EngineSnapshot{Policy=new(){Groups=[g]}};Assert.ThrowsExactly<ArgumentException>(()=>ExceptionCatalog.UpdateAnnotations(state,g.Id,[new("*unlisted*")]));Assert.ThrowsExactly<ArgumentException>(()=>ExceptionCatalog.ValidateEntries([new("example.com",new string('a',501))]));Assert.ThrowsExactly<ArgumentException>(()=>ExceptionCatalog.ValidateEntries([new("example.com","","a\nb")]));Assert.ThrowsExactly<ArgumentException>(()=>ExceptionCatalog.ValidateEntries([new("example.com"),new("EXAMPLE.COM")]));Assert.ThrowsExactly<ArgumentException>(()=>PolicyValidation.Validate(state.Policy with{Groups=[g with{WebsiteExceptionDetails=[new("other.com","bad")] }]}));}
    sealed class Clock:IClock {public string BootId=>"notes";public long Uptime{get;set;}public long AwakeMilliseconds=>Uptime;public DateTimeOffset UtcNow=>DateTimeOffset.Parse("2026-11-03T12:00:00Z").AddMilliseconds(Uptime);}
    [TestMethod] public async Task ProtectedCommandRequiresTokenAndMetadataPersistsWithoutUnlocking(){string dir=Path.Combine(Environment.GetEnvironmentVariable("AICT_TEST_ROOT")??Path.GetTempPath(),"notes-api-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var c=new Clock();using var a=new Authority(StateRepository.CreateNew(Path.Combine(dir,"engine.sqlite"),Authority.Initial(c)),c,[]);var g=Group();var s=(await a.Handle(new())).Status!;await a.Handle(new(){Command=Command.SubmitPolicy,EditToken=s.EditToken,Policy=new(){Groups=[g],ChangeDelay=TimeSpan.FromMinutes(1)}});s=(await a.Handle(new())).Status!;await a.Handle(new(){Command=Command.SubmitPolicy,EditToken=s.EditToken,Policy=s.Policy with{Groups=[g with{Enabled=false}]}});s=(await a.Handle(new())).Status!;var queued=s.Pending!;var response=await a.Handle(new(){Command=Command.UpdateWebsiteAnnotations,EditToken=s.EditToken,Annotations=new(g.Id,[new(g.WebsiteExceptions[0],"英语课","学习")])});Assert.IsTrue(response.Ok,response.Message);Assert.IsTrue(response.Status!.Policy.Groups[0].Enabled);Assert.AreEqual(queued.Id,response.Status.Pending!.Id);Assert.AreEqual(queued.NotBeforeUtc,response.Status.Pending.NotBeforeUtc);Assert.AreEqual("英语课",ExceptionCatalog.Rows(response.Status.Policy.Groups[0])[0].Note);Assert.IsFalse((await a.Handle(new(){Command=Command.UpdateWebsiteAnnotations,EditToken=s.EditToken,Annotations=new(g.Id,[new(g.WebsiteExceptions[0],"stale")])})).Ok);Assert.ThrowsExactly<ArgumentException>(()=>new Request{Command=Command.UpdateWebsiteAnnotations,Annotations=new(g.Id,[])}.Validate());}
}
